def emit(**v):print(json.dumps(v,separators=(",",":")),flush=True)
def identity(p):
 with open(p,"rb") as f:
  a=os.fstat(f.fileno());h=hashlib.sha256();n=0
  for b in iter(lambda:f.read(262144),b""):h.update(b);n+=len(b)
  z=os.fstat(f.fileno())
  if (a.st_dev,a.st_ino,a.st_size,a.st_mtime_ns,a.st_ctime_ns)!=(z.st_dev,z.st_ino,z.st_size,z.st_mtime_ns,z.st_ctime_ns):raise RuntimeError("Original file changed")
 return {"bytes":n,"sha256":h.hexdigest(),"device":a.st_dev,"inode":a.st_ino}
